  acImbue: "НАДЕЛИТЬ",
  descNewborn: "Заклинание в данный момент не наделено, и призовёт молодого элементаля без дальнобойной атаки. Вы можете использовать опознанное Зелье Алхимического огня, Зелье Холода, Свиток Перезарядки или Свиток Превращения, для наполнения заклинания, чтобы в будущем призывать сильного элементаля!",
  descFire: "Заклинание сейчас горячее на ощупь. Оно будет вызывать огненного элементаля. Вы можете наделить заклинание другим предметом, но оно потеряет текущее наполнение.",
  descFrost: "Заклинание сейчас холодное на ощупь. Оно будет вызывать ледяного элементаля. Вы можете наделить заклинание другим предметом, но оно потеряет текущее наполнение.",
  descShock: "Заклинание сейчас излучает статическую энергию. Оно будет вызывать электрического элементаля. Вы можете наделить заклинание другим предметом, но оно потеряет текущее наполнение.",
  descChaos: "Заклинание сейчас излучает хаотическую энергию. Оно будет вызывать хаотического элементаля. Вы можете наделить заклинание другим предметом, но оно потеряет текущее наполнение.",
