  buff_ooze: "едкая слизь",
  buff_enthralled: "зачарованный",
  guideTitle: "Учебник алхимии",
  page_potions_title: "Вступление и зелья",
  page_potions_body: "Добро пожаловать в курс практических занятий по алхимии! Эта книга — справочник с рецептами для создания предметов в алхимическом котле.\nНачнём с самого знакового рецпта: Зелье.\n\nИспользуйте три семени, чтобы сварить случайное зелье! Каждое семя соответствует определённому зелью, и если использовать несколько одинаковых семян, шанс получить зелье, связанное с этими семенами, увеличивается.",
  page_stones_title: "Создание рунных камней",
  page_stones_body: "Если поместить свиток в алхимический котел, то его магия впитается в два камня на дне. Это создает рунные камни и опознаёт свиток!",
  page_energy_food_title: "Энергия и пища",
  page_energy_food_body: "Множество рецептов требуют кристаллы алхимической энергии, которую можно получить путём расщепления расходных предметов в алхимическом котле. Расщепление зелий и свитков опознаёт их.\n\nНекоторые рецепты, для которых нужна энергия, магические, но эти больше напоминают обычную готовку.",
  page_exotic_potions_title: "Особые зелья",
  page_exotic_potions_body: "Смешивая зелья с энергией, вы можете создать особые зелья. Эти зелья имеют более сильные эффекты, но часто используются в других ситуациях.",
  page_exotic_scrolls_title: "Особые свитки",
  page_exotic_scrolls_body: "Особые свитки могут быть получены путём варки свитка и энергии. Они немного сильнее и гораздо затратнее особых зелий.",
  page_bombs_title: "Зачарованные бомбы",
  page_bombs_body: "Обычная бомба с порохом может быть смешана с некоторыми ингредиентами для того, чтобы получить зачарованную бомбу.",
  page_weapons_title: "Улучшение оружия",
  page_weapons_body: "Некоторые из лёгких, а ещё больше – из магических оружий можно использовать в алхимии!\n\nКаждый комплект метательного оружия при переработке даёт достаточно жидкого металла, чтобы полностью починить другой комплект того же уровня и редкости. Обратите внимание, что переработка комплекта уничтожит весь комплект, даже если он не полный!\n\nОдна палочка даёт достаточно магической смолы, чтобы улучшить две палочки того же уровня, но не выше +3.",
  page_brews_elixirs_title: "Экстракты и Эликсиры",
  page_brews_elixirs_body: "Экстракты и эликсиры это более продвинутые зелья, имеющие сразу несколько эффектов обычно лишь при одном употреблении.",
  page_spells_title: "Создание заклинаний",
  page_spells_body: "Заклинания имеют форму кристаллов и содержат различные эффекты, которые можно использовать несколько раз.",
