  helpText: [
    'Tap a cell to walk there, tap a monster to attack it.',
    'Tap an item on the floor to pick it up. The backpack (bottom right) holds your loot: drink, read, eat, equip, drop.',
    'Heroes grow hungry: eat in time, for a starving hero does not heal.',
    'The slot next to the backpack holds darts, a boomerang or a wand: tap it, then the target.',
    'Tap your hero or the magnifier to search for hidden doors and traps.',
    'The hourglass waits a turn; hold it to rest until healed.',
    'The question mark, then a tap on the map, tells you about a monster, an item or a place. This help is in the menu.',
    'Walk onto the stairs to go deeper. Goo waits on the fifth floor, Tengu on the tenth, DM-300 on the fifteenth, the King of Dwarves on the twentieth, Yog-Dzewa on the twenty-fifth; the Amulet of Yendor lies below it.',
    'Tap a chasm beside you to jump in: you land hurt on the depth below. An ankh from a shop brings you back once from death.',
    'Pinch (or the mouse wheel, + and −) to zoom out over the map or in on the details; drag to look around — a step brings the view back.',
  ],
