  corrupted: (mob: string) => `The ${mob} rises again, on your side.`,
  tipped: (n: number, name: string) => `You tip ${n} darts: ${name}.`,
  burntUp: (name: string) => `Your ${name} burns up!`,
  ateOk: 'That food tasted ok.',
  shatterPot: 'Shatter',
  inBags: 'In bags and on the key ring:',
  toQuickslot: 'Put in the quickslot',
  quickslotShort: 'Quickslot',
  quickslotN: (n: number) => `Slot ${n}`,
  dragToDrop: 'Let go here to drop it',
  mateTurn: 'their move…',
  mateOffline: 'away',
  mateFallen: 'fallen',
  mateOnDepth: (depth: number) => `on depth ${depth}`,
  bagAll: 'All', bagPotions: 'Potions', bagScrolls: 'Scrolls', bagGear: 'Gear',
  wornChip: 'worn',
  orHold: 'or hold the slot',
  holdTitle: 'Hold a slot',
  holdText: 'for its quick action: drink, eat, put on.',
  keysCount: (n: number) => `Keys: ${n}`,
  badgeEarned: (what: string) => `New badge: ${what}`,
  badges: 'Badges',
  badgesCount: (got: number, all: number) => `Earned ${got} of ${all}.`,
  examinePrompt: 'Tap a cell to examine it.',
  examineUnknown: 'You do not know what is there.',
  examineHealth: (hp: number, ht: number) => `Health: ${hp}/${ht}.`,
  levelShort: 'level',
