/** Russian plural forms: 1 день, 2 дня, 5 дней. */
function plural(n: number, one: string, few: string, many: string): string {
  const tens = n % 100;
  const ones = n % 10;
  if (tens >= 11 && tens <= 14) return many;
  return ones === 1 ? one : ones >= 2 && ones <= 4 ? few : many;
}

function capitalize(text: string): string {
  return text.charAt(0).toUpperCase() + text.slice(1);
}

function language(): 'ru' | 'en' {
  const telegram = (globalThis as { Telegram?: { WebApp?: { initDataUnsafe?: { user?: { language_code?: string } } } } })
    .Telegram?.WebApp?.initDataUnsafe?.user?.language_code;
  let chosen: string | null = null;
  try {
    // Chosen in the settings; otherwise as in Telegram, or the browser.
    chosen = localStorage.getItem('pd-lang');
  } catch {
    // Storage blocked: go by Telegram.
  }
  const code = new URLSearchParams(location.search).get('lang') ?? chosen ?? telegram ?? navigator.language ?? 'en';
  return /^(ru|uk|be|kk)/i.test(code) ? 'ru' : 'en';
}

export const lang = language();
export const t: Strings = lang === 'ru' ? ru : en;
/** For dates and numbers in the language of the text around them. */
export const locale = lang === 'ru' ? 'ru-RU' : 'en-US';
if (typeof document !== 'undefined') document.documentElement.lang = lang;
export { capitalize };
/** Both languages' texts, for the tests that check one against the other. */
export { en as enStrings, ru as ruStrings };

/** Messages.format: a Shattered template's %s, %d, %.1f and %1$d filled in order (or by number), %% a percent sign. */
export function fill(template: string, ...args: Array<string | number>): string {
  let next = 0;
  return template.replace(/%(?:(\d+)\$)?([-0-9.]*)([sdf%])/g, (_whole, at: string | undefined, _flags: string, conv: string) => {
    if (conv === '%') return '%';
    const value = args[at ? Number(at) - 1 : next++];
    if (value === undefined) return '';
    if (conv === 'd' && typeof value === 'number') return String(Math.trunc(value));
    return String(value);
  });
}
